const d=[
 {label:'Asia',v:4.8,c:'accent'},
 {label:'Africa',v:1.5,c:'a3'},
 {label:'Europe',v:0.74,c:'a2'},
 {label:'N. America',v:0.6,c:'a2'},
 {label:'S. America',v:0.44,c:'a3'},
 {label:'Oceania',v:0.046,c:'warn'}];
const rows=d.map((r,i)=>{const y=170+i*82,kk=api.ease(api.seg(t,0.5+i*0.4,1.8+i*0.4));
 api.text(r.label,30,y,{size:18,k:kk});
 const w=Math.max(6,(api.w-70)*r.v/4.8*0.75)*kk;
 api.rect(30,y+14,w,26,{c:r.c,fill:r.c});
 api.counter(r.v,36+w,y+34,{k:kk,suf:' B',d:2,size:18});
 return y;});
