api.look('agent');
const cx=api.w/2;
api.text('Growth per year',cx,90,{size:30,align:'center'});
api.bars([
 {label:'Africa',v:2.3,c:'accent'},
 {label:'Oceania',v:1.2,c:'a3'},
 {label:'S. America',v:0.6,c:'a3'},
 {label:'Asia',v:0.5,c:'a2'},
