const cx=api.w/2;
api.text('People by 2100',cx,90,{size:30,align:'center'});
api.lineChart([
 {v:[1.5,2.1,2.9,3.6,3.9],c:'accent',label:'Africa'},
 {v:[4.8,5.2,5.1,4.7,4.0],c:'a2',label:'Asia'}],
